import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.yMGLHqpH.js";const g=JSON.parse('{"title":"Gentoo / Calculate","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/gentoo.md","filePath":"zh-TW/guide/gentoo.md"}'),o={name:"zh-TW/guide/gentoo.md"};function n(r,e,h,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="gentoo-calculate" tabindex="-1">Gentoo / Calculate <a class="header-anchor" href="#gentoo-calculate" aria-label="標題連結： &quot;Gentoo / Calculate&quot;">​</a></h1><p>Gentoo 使用者可透過 <a href="https://github.com/gentoo-zh/overlay/tree/master/net-proxy/dae" target="_blank" rel="noreferrer">gentoo-zh overlay</a> 安裝 <code>net-proxy/dae</code>。此套件由 Gentoo 社群維護，使用 Portage 管理。本網站的 APT/RPM 版本表對應另一個套件來源。</p><p>以下指令以 root 身分執行，測試關鍵字範例適用於 amd64 系統。</p><h2 id="_1-新增並同步-overlay" tabindex="-1">1. 新增並同步 overlay <a class="header-anchor" href="#_1-新增並同步-overlay" aria-label="標題連結： &quot;1. 新增並同步 overlay&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-eselect/eselect-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-vcs/git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eselect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/gentoo-zh/overlay.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emaint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span></span></code></pre></div><p>如果已經設定 gentoo-zh，只需執行同步指令。鏡像選擇與手動設定方法請見 <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay 文件</a>。</p><h2 id="_2-接受測試關鍵字" tabindex="-1">2. 接受測試關鍵字 <a class="header-anchor" href="#_2-接受測試關鍵字" aria-label="標題連結： &quot;2. 接受測試關鍵字&quot;">​</a></h2><p>使用穩定關鍵字的 amd64 系統需要在 <code>package.accept_keywords</code> 中新增以下設定。如果 <code>/etc/portage/package.accept_keywords</code> 是目錄，可寫入其中的 <code>/etc/portage/package.accept_keywords/dae</code> 檔案；如果它是檔案，則直接在該檔案中新增。</p><div class="language-text vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net-proxy/dae::gentoo-zh ~amd64</span></span></code></pre></div><p>已全域接受 <code>~amd64</code> 的系統可略過此步驟。其他架構需先檢查所選 ebuild 的 <code>KEYWORDS</code>，再選擇對應的關鍵字。</p><h2 id="_3-安裝-dae" tabindex="-1">3. 安裝 dae <a class="header-anchor" href="#_3-安裝-dae" aria-label="標題連結： &quot;3. 安裝 dae&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> net-proxy/dae::gentoo-zh</span></span></code></pre></div><p>檢查 Portage 提供的核心設定提示。ebuild 會安裝 OpenRC、systemd 服務檔案，並將設定範例放在 <code>/usr/share/dae/config.dae.example</code>。啟動服務前應先完成 dae 設定，詳見 <a href="https://github.com/daeuniverse/dae#readme" target="_blank" rel="noreferrer">dae 文件</a>。</p><h2 id="選用-鏡像與二進位套件" tabindex="-1">選用：鏡像與二進位套件 <a class="header-anchor" href="#選用-鏡像與二進位套件" aria-label="標題連結： &quot;選用：鏡像與二進位套件&quot;">​</a></h2><p>Distfiles 鏡像、binhost 頻道與簽章驗證的設定方法請見 <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay 文件</a>。可用的二進位套件以<a href="https://distfiles.gentoozh.org/packages" target="_blank" rel="noreferrer">套件列表</a>為準；沒有合適的二進位套件時，Portage 可以從原始碼編譯。</p>`,15)])])}const k=a(o,[["render",n]]);export{g as __pageData,k as default};
